#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Admin logins happen only in Windows Sandbox (ADR-0012). This folder exists
# only there, through the mapping in v1be-admin.wsb.
if [[ ! -d /c/code/v1be-infra/sandbox ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

banner "AWS account: management account with root MFA"

# Activation can take up to 24 hours, so a later run can skip the sign-up.
if confirm "Is your AWS account already activated (a re-run)?"; then
  _STAGE_INDEX=6
else

stage "Before you start"
say "This Sandbox has no shared clipboard, so you'll type values by hand."
say "Have these ready:"
step "Your phone, for the email code, the SMS code and the authenticator app."
step "A credit or debit card. AWS may hold about USD 1 for 3-5 days to verify it."
step "A root password in your password manager, made of 5-6 random words."
step "A root email. Suggested: your Gmail with +management before the @."
warn "Read email on your phone. Don't sign in to Gmail in this Sandbox."
warn "Never paste the password, codes or card details into Claude."
pause "Press Enter when you have them."

stage "Email and account name"
open_url "https://signin.aws.amazon.com/signup?request_type=register"
step "Check the page asks for a root user email and an AWS account name."
warn "Google, GitHub or Apple login buttons, or a request for your own name, mean"
warn "the wrong sign-up. That one has no root user and AWS manages the SCPs."
if ! confirm "Does the page ask for a root user email and an AWS account name?"; then
  warn "Stopping before anything is created. Tell Claude what the page shows."
  exit 1
fi
step "Enter the root email."
step "For the account name, enter v1be-management."
step "Choose Verify email address, then enter the code from your phone."
pause "Press Enter when the email is verified."

stage "Root password"
step "Type the password from your password manager, twice."
step "It needs 3 of: uppercase, lowercase, numbers, symbols."
step "Choose Continue."
pause "Press Enter when it's accepted."

stage "Paid plan and contact details"
warn "Choose the Paid plan, not the Free plan."
note "You get the same USD 100 credit. Joining Organizations in step 5 would"
note "force an upgrade from Free anyway, and could cost a Free account its credits."
step "Choose the Paid account plan."
step "If it asks for an account type, choose Personal."
step "Enter your real contact details and a phone number you'll keep."
note "AWS uses that phone and the root email to recover a lost MFA device."
step "Read and accept the AWS Customer Agreement."
pause "Press Enter when you've reached the billing page."

stage "Payment, phone and support"
step "Enter your card and billing address."
step "If asked, confirm your identity by SMS and enter the code."
step "Choose the free Basic support plan, not a paid one."
step "Choose Complete sign up."
pause "Press Enter when AWS says the account is being activated."

stage "Wait for activation"
say "AWS emails you when the account is active. This usually takes a few minutes,"
say "but can take up to 24 hours. Check spam on your phone too."
note "If it's slow, press Ctrl-C and re-run later. Answer y to the first question."
pause "Press Enter when the activation email has arrived."

fi

stage "Root MFA"
warn "Use the authenticator app on your phone, not a passkey."
note "A passkey saved in this Sandbox is deleted when the Sandbox closes."
open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
step "Sign in with Root user, the root email and the password."
note "If AWS asks you to register MFA at sign-in, the steps below are the same."
warn "Global on this IAM page is normal. Open https://console.aws.amazon.com/console/home in a new tab."
warn "A Manage projects menu, or no Region list there, means the Builder ID sign-up."
if ! confirm "Did Root user sign-in work, and does console home list Regions such as Singapore?"; then
  warn "Stopping before MFA. Tell Claude what happened. Don't activate anything."
  exit 1
fi
step "Under Multi-Factor Authentication (MFA), choose Assign MFA device."
step "Name it root-phone, choose Authenticator app, then Next."
step "Choose Show QR code and scan it with your phone."
step "Choose Show secret key and write it on paper, kept away from this laptop."
step "Enter two codes in a row in MFA code 1 and MFA code 2, then Add MFA."
pause "Press Enter when the device is listed."

stage "Final checks"
say "Check each one. Step 9 adds a second MFA method later."
step "On this same page, Access keys must be empty. Never create one for root."
open_url "https://console.aws.amazon.com/costmanagement/"
step "On the billing page, look for an Upgrade plan option."
note "If there is one, this account is on the Free plan. Choose Upgrade plan,"
note "then Upgrade account, now. It's one-way, and it's what the plan wants."
step "Create nothing else, and don't enable Organizations or Identity Center yet."
pause "Press Enter when you've checked both."

finish
say "Tell Claude these three things:"
step "The root MFA device is listed."
step "Access keys is empty."
step "Whether the Upgrade plan option was there."
note "No password, codes, secret key or card details are needed, and no account ID."
}

run_wizard "$@"; exit
